def is_nested(string):
    stack = []
    has_nested = False

    for char in string:
        if char == '[':
            stack.append(char)
        elif char == ']':
            if stack:
                if stack[-1] == '[':
                    stack.pop()
                    if stack:  # If stack is not empty, we have a nested structure
                        has_nested = True
            else:
                return False  # Unmatched closing bracket

    return has_nested

